// Traditional Function
function addOld(a, b) {
  return a + b;
}

// Arrow Function (Explicit return)
const addModern = (a, b) => {
  return a + b;
}

// Arrow Function (Implicit return - the cleanest way)
const addShort = (a, b) => a + b;

console.log(addShort(5, 10)); // Prints 15

const numbers = [1, 2, 3, 4, 5];

// Map: Multiply all by 2
const doubled = numbers.map(num => num * 2);
console.log("Doubled:", doubled); // [2, 4, 6, 8, 10]

// Filter: Only keep numbers greater than 3
const largeNums = numbers.filter(num => num > 3);
console.log("Large Nums:", largeNums); // [4, 5]

// Reduce: Sum all numbers
const sum = numbers.reduce((total, num) => total + num, 0);
console.log("Total Sum:", sum); // 15

