const video = {
  title: "JS Tutorial",
  play() {
    // 'this' refers to the video object
    console.log(`Playing ${this.title}`);
  },
  showTags() {
    const tags = ['js', 'web', 'frontend'];
    // Using an arrow function keeps 'this' pointing to the video object!
    tags.forEach((tag) => {
      console.log(this.title, tag);
    });
  }
};

video.play();
video.showTags();

