const emailInput = "user@example.com";

// A basic regex for email validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// .test() returns a boolean
const isValid = emailRegex.test(emailInput);
console.log("Is valid email?", isValid);

// String replacement using regex
const text = "The quick brown fox.";
// Replace all vowels (g flag) case-insensitive (i flag) with '*'
const censored = text.replace(/[aeiou]/gi, '*');
console.log(censored); // Th* q**ck br*wn f*x.

// Run once after 2 seconds
const timeoutId = setTimeout(() => {
  console.log("Delayed message!");
}, 2000);

// Run every 1 second
let counter = 0;
const intervalId = setInterval(() => {
  counter++;
  console.log(`Interval hit: ${counter}`);

  // Stop the interval after 3 hits
  if (counter === 3) {
    clearInterval(intervalId);
    console.log("Interval stopped.");
  }
}, 1000);

