// Closure Example
function createCounter() {
  let count = 0; // Private variable

  return function() {
    count++; // Inner function remembers 'count'
    return count;
  }
}

const counter = createCounter();
console.log(counter()); // 1
console.log(counter()); // 2
// We cannot access 'count' directly from the outside!

const users = [
  { id: 1, name: 'Alice', active: true },
  { id: 2, name: 'Bob', active: false },
  { id: 3, name: 'Charlie', active: true }
];

// .find() - Returns the first match (Bob's object)
const inactiveUser = users.find(user => user.active === false);
console.log(inactiveUser.name);

// .some() - Returns true because at least one is inactive
const hasInactive = users.some(user => user.active === false);

// .every() - Returns false because Bob is inactive
const allActive = users.every(user => user.active === true);

